CREATE PROCEDURE sp_rpt_IT_Menu_Item_Count_Validation -- Add the parameters for the stored procedure here 	( 		@StartDate date = null, 		@EndDate date = null, 		@StoreGrouping int = 8, 		@StoreGroup varchar(1500) = '1040',         @Category varchar(50) = '* Consolidated Salads' 	) AS /** ## Procedure Name       *[toast].[dbo].[sp_rpt_IT_Menu_Item_Count_Validation]*   **Procedure Type**      *stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             20260225   **Report Name**         *IT Menu Item Count Validation*   **Summary**   *summary of report*      ### Parameters   ```sql   StartDate date              Start date of the range   EndDate date                End Date of the range   StoreGrouping int           The grouping type of stores   StoreGroup varchar(1500)    The store / store group / dma / etc to run for   Category varchar(50)        Which category to run the validation for   ```      ### Output    *describe the fields of the result set   (if code is in this description, block the code with three backticks on a blank line above and below the code block.   After the first tripple backtick, place the name of the language the code is written in.   See the example of this in the Parameters section above.  Follow the second tuple with a blank line.*      ### Change History   **Change Date:**            *YYYYMMDD*   **Author:**                 *Last, First < email address >*   **Version**:                ##   **Change:**   *detail change here*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;      declare          -- If this is for a table build, then Tab, if not, then Proc 	    @RunType varchar(4) = 'Proc'          -- The time the procedure begins running 	   ,@StartTime datetime = getdate()        -- The database the procedure is running in 	   ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself 	   ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error 	   ,@ErrorNumber int = 0 	   ,@ErrorMessage varchar(250) = '' 	   ,@ErrorLine int = 0             BEGIN TRY                 -- if this is a table build, perform it as a transaction         if (@RunType = 'Tab') begin transaction;                  DECLARE @SDate date         DECLARE @EDate date          SET @SDate =              CASE                 WHEN @StartDate IS NULL THEN DATEADD(mm,-1,DATEADD(mm,DATEDIFF(mm,0,GETDATE()),0))                 ELSE @StartDate             END          SET @EDate =             CASE                 WHEN @EndDate IS NULL THEN DATEADD(ms,-3,DATEADD(mm,0,DATEADD(mm,DATEDIFF(mm,0,GETDATE()),0)))                 ELSE @EndDate             END  		declare @Params varchar(2000) = (select @StoreGrouping as StoreGrouping, @StoreGroup as StoreGroup, @SDate as SDate, @EDate as EDate for json path)          select *         into #StoresIncluded         from dev_aloha.dbo.get_StoresIncluded (@StoreGrouping, @StoreGroup, @EDate)      	declare @CatID int          set @CatID = (select distinct consolcatid from toast.dbo.cfg_tags where Tag_Name = @Category)          create table #Interim         (             DateOfBusiness date,             StoreGUID char(36),             StoreNum int,             Recipe varchar(50),             ItemMLI varchar(25),             Equiv decimal(3,1),             ItemID_T int,             Item_Name_T varchar(100),             ItemID_A int,             Item_Name_A varchar(100),             CYItemCount float,             LYItemCount float         )          insert into #Interim (DateOfBusiness, StoreGUID, StoreNum, ItemMLI, Equiv, ItemID_T, Item_Name_T, ItemID_A, Item_Name_A, CYItemCount, LYItemCount)         select distinct             c.date,             si.StoreGUID,             si.StoreID,             mi.MultiLocationId,             0.0,             mi.Item_PLU,             mi.item_name,             0,             '',             0,             0         from #StoresIncluded si         join toast.dbo.cfg_menu_items mi with (NOLOCK)         on si.StoreGUID = mi.Store_GUID         join toast.dbo.cfg_map_item_tags mit         on mi.MultiLocationId = mit.MultiLocationId         and mi.Store_GUID = mit.Store_GUID         join toast.dbo.cfg_tags t         on mit.Tag_GUID = t.Tag_GUID         and mit.Store_GUID = t.StoreGuid         join dev_aloha.dbo.CalendarV2 c         on 1 = 1         where t.ConsolCatID = @CatID         and c.date between @SDate and @EDate         and mi.Item_Name not like 'Z-%'         order by c.date, si.StoreGUID, si.StoreID, mi.MultiLocationId, mi.Item_PLU, mi.item_name          IF @CatID != 27         begin             delete from #Interim             where item_name_t like 'CAT %'         end          update #Interim set             Equiv = TRY_CAST(substring(j.name, 4, LEN(j.name)-3) AS DECIMAL(3,1))         from #Interim i         join toast.dbo.cfg_menu_items mi         on convert(varchar(19),i.ItemMLI) = convert(varchar(19),mi.MultiLocationId)         cross apply             openjson(item_tags)             with (guid char(36) '$.guid',                   name varchar(75) '$.name'             ) as j         where j.name like 'EE%'          update #Interim set             ItemID_A = p.AlohaPLU         from #Interim r         join toast.dbo.cfg_map_PLU_Toast_to_Aloha p         on r.ItemID_T = p.ToastPLU          update #Interim set             Item_Name_A = LongName         from #Interim r         join dev_aloha.dbo.item i         on r.ItemID_A = i.ItemID          update #Interim set             Recipe = t.Tag_Name         from #Interim i         join toast.dbo.cfg_map_item_tags mit         on i.ItemMLI = mit.MultiLocationId         and i.StoreGUID = mit.Store_GUID         join toast.dbo.cfg_tags t         on mit.Tag_GUID = t.Tag_GUID         and mit.Store_GUID = t.StoreGuid         where t.Tag_Name not like '* Cons%'         and t.Tag_Name not like '%Cater%'         and t.Tag_Name not like '%Guest%'         and t.Tag_Name not like '%LTO%'         and t.Tag_Name not like 'EE%'          select             i.DateOfBusiness, i.StoreNum, i.Recipe, convert(char(19),i.itemmli) itemmli, sum(hi.Quantity) CYCount         into #CY         from #Interim i         join toast.dbo.hstItem hi         on i.DateOfBusiness = hi.DateOfBusiness         and i.StoreNum = hi.StoreNum         and i.ItemMLI = hi.MenuItemMLI         where hi.voided = 0         group by i.DateOfBusiness, i.StoreNum, i.Recipe, i.itemmli         order by i.DateOfBusiness, i.StoreNum, i.Recipe, i.itemmli           update #Interim set             CYItemCount = CYCount         from #Interim i         join #CY cy         on i.DateOfBusiness = cy.DateOfBusiness         and i.StoreNum = cy.StoreNum         and i.itemmli = cy.itemmli          delete from #Interim         where Item_Name_T like '%uga%'         and StoreNum != 1184         and (CYItemCount is null              or              CYItemCount = 0)          select             DateOfBusiness,              StoreNum,              Recipe,              Equiv as EntreeEquivalent,             string_agg(convert(char(19),ItemMLI), ' / ') within group (order by ItemMLI asc, Equiv) ItemMLI,              string_agg(ItemID_T, ' / ') within group (order by ItemMLI asc, Equiv) ItemID_T,              string_agg(Item_Name_T, ' / ') within group (order by ItemMLI asc, Equiv) Item_Name_T,             ItemID_a,              Item_Name_A,             sum(CYItemCount) CYItemCount, sum(LYItemCount) LYItemCount         into #Results         from #Interim         group by DateOfBusiness, StoreNum, Recipe, Equiv, ItemID_a, Item_Name_A         order by StoreNum, Recipe, ItemMLI, Equiv, ItemID_T, Item_Name_T, ItemID_A, Item_Name_A          select             dateadd(year,1,DateOfBusiness) DateOfBusiness,             si.StoreID,             mm.fkitemid,             i.longname,             sum(mm.itemcount) LYItemCount         into #LYCounts         from dev_aloha.dbo.MenuMix mm         join dev_aloha.dbo.item i         on mm.fkitemid = i.ItemID         join dev_aloha.dbo.categoryitem ci         on i.itemid = ci.FKItemId         join #StoresIncluded si         on mm.fkstoreid = si.StoreID         where mm.DateOfBusiness between dateadd(year,-1,@SDate) and dateadd(year,-1,@EDate)         and ci.CategoryItemId = @CatID         group by dateadd(year,1,DateOfBusiness), si.storeid, mm.fkitemid, i.LongName          merge #Results r         using #LYCounts l         on r.dateofbusiness = l.dateofbusiness         and r.storenum = l.storeid         and r.itemid_a = l.fkitemid         when matched then update set             LYItemCount = l.LYItemCount,             Item_Name_A = l.longname         when not matched by target then             insert(DateOfBusiness, StoreNum, ItemID_A, Item_Name_T, Item_Name_A, LYItemCount)             values(l.DateOfBusiness, l.StoreID, l.FKItemID, '', l.LongName, l.LyItemCount);          if @StoreGrouping = 8             begin                 select                      StoreNum,                     si.StoreName,                     isnull(Recipe,'') Recipe,                     isnull(EntreeEquivalent,0) EntreeEquivalents,                     isnull(ItemMLI,'') ItemMLI,                     isnull(ItemID_T,'') ItemID_T,                     isnull(Item_Name_T,'') Item_Name_T,                     isnull(ItemID_A,'')ItemID_A,                     isnull(Item_Name_A,'') Item_Name_A,                     isnull(sum(CYItemCount),0) CYItemCount,                     isnull(sum(LYItemCount),0) LYItemCount,                     '' BlankCol,                     isnull(sum(CYItemCount),0) * isnull(EntreeEquivalent,0) CY_Equiv_Count,                     isnull(sum(LYItemCount),0) * isnull(EntreeEquivalent,0) LY_Equiv_Count                 from #Results r                 join #StoresIncluded si                 on r.storenum = si.storeid                 group by StoreNum, StoreName, Recipe, ItemMLI, EntreeEquivalent, ItemID_T, Item_Name_T, ItemID_A, Item_Name_A                 order by StoreNum, StoreName, Recipe, EntreeEquivalent, Item_Name_T, Item_Name_A, ItemID_A             end                      if @StoreGrouping = 9             begin                 select                      isnull(Recipe,'') Recipe,                     isnull(EntreeEquivalent,0) EntreeEquivalents,                     isnull(ItemMLI,'') ItemMLI,                     isnull(ItemID_T,'') ItemID_T,                     isnull(Item_Name_T,'') Item_Name_T,                     isnull(ItemID_A,'')ItemID_A,                     isnull(Item_Name_A,'') Item_Name_A,                     isnull(sum(CYItemCount),0) CYItemCount,                     isnull(sum(LYItemCount),0) LYItemCount,                     '' BlankCol,                     isnull(sum(CYItemCount),0) * isnull(EntreeEquivalent,0) CY_Equiv_Count,                     isnull(sum(LYItemCount),0) * isnull(EntreeEquivalent,0) LY_Equiv_Count                 from #Results r                 join #StoresIncluded si                 on r.storenum = si.storeid                 group by Recipe, ItemMLI, EntreeEquivalent, ItemID_T, Item_Name_T, ItemID_A, Item_Name_A                 order by Recipe, EntreeEquivalent, Item_Name_T, Item_Name_A, ItemID_A             end          drop table #StoresIncluded         drop table #Results         drop table #LYCounts         drop table #Interim         drop table #CY                  -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName 			,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine 			,@Params = @Params;         THROW;     END CATCH END